import 'package:flutter/material.dart';import '../../core/money.dart';import '../../data/local_database.dart';
class CashScreen extends StatefulWidget{const CashScreen({super.key});@override State<CashScreen> createState()=>_CashScreenState();}
class _CashScreenState extends State<CashScreen>{
Future<void> add(String table,String type)async{final amount=TextEditingController();final note=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(type=='deposit'?'إيداع':'سحب / مصروف'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'المبلغ بالريال')),TextField(controller:note,decoration:const InputDecoration(labelText:'البيان'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('حفظ'))]));if(ok==true){final cents=Money.parseHalalas(amount.text);if(cents<=0)return;final balance=await LocalDatabase.instance.balance(table);if(type!='deposit'&&cents>balance){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('الرصيد غير كافٍ')));return;}await(await LocalDatabase.instance.database).insert(table,{'created_at':DateTime.now().toIso8601String(),'type':type,'amount_halalas':cents,'note':note.text});if(mounted)setState((){});}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('الصندوق والشبكة')),body:FutureBuilder<List<int>>(future:Future.wait([LocalDatabase.instance.balance('cash_transactions'),LocalDatabase.instance.balance('network_transactions')]),builder:(c,s)=>!s.hasData?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(16),children:[_account(c,'الصندوق النقدي',s.data![0],'cash_transactions'),_account(c,'حساب الشبكة',s.data![1],'network_transactions')])));}
Widget _account(BuildContext c,String title,int amount,String table)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Text(title),Text(Money.format(amount),style:const TextStyle(fontSize:26,fontWeight:FontWeight.bold)),Row(mainAxisAlignment:MainAxisAlignment.center,children:[TextButton(onPressed:()=>add(table,'deposit'),child:const Text('إيداع')),TextButton(onPressed:()=>add(table,'withdrawal'),child:const Text('سحب'))])])));}
}
